// Log Seguimiento
return [{
  json: {
    status: 'logged',
    category: 'SEGUIMIENTO',
    user_id: $('Parse Classification').first().json.user_id,
    message: $('Parse Classification').first().json.originalMessage,
    timestamp: new Date().toISOString()
  }
}];

// User Response - Send AI response back to user
const ragResponse = $input.first().json;
const userData = $('Parse Classification').first().json;

return [{
  json: {
    chatId: userData.user_id,
    text: ragResponse.message || ragResponse.content || 'Gracias por su consulta. Un asesor se comunicará pronto.'
  }
}];

// Metrics Logger
const data = $('Parse Classification').first().json;

const metrics = {
  timestamp: new Date().toISOString(),
  channel: data.source,
  category: data.category,
  priority: data.priority,
  response_time_ms: Date.now() - new Date(data.timestamp).getTime(),
  user_id: data.user_id
};

// Log to console (in production, send to metrics DB)
console.log('METRICS:', JSON.stringify(metrics));

return [{ json: metrics }];
